    H=[];V=[]
    for r_ in range(7):
        c_=0
        while c_<7:
            if mask[r_][c_]:
                s=c_
                while c_<7 and mask[r_][c_]: c_+=1
                if c_-s>=minlen: H.append((r_,s,c_-1))
            else: c_+=1
    for c_ in range(7):
        r_=0
        while r_<7:
            if mask[r_][c_]:
                s=r_
                while r_<7 and mask[r_][c_]: r_+=1
                if r_-s>=minlen: V.append((c_,s,r_-1))
